import React, { useEffect, useState } from "react";
import { fetchDeliveries } from "../api/deliveryApi";
import { Link } from "react-router-dom";
import axios from "axios";

export default function DeliveryDashboard() {
  const [deliveries, setDeliveries] = useState<any[]>([]);

  useEffect(() => {
    fetchDeliveries().then((res) => setDeliveries(res.data));
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm("Are you sure you want to delete this delivery?")) return;
    try {
      await axios.delete(`http://localhost:5000/api/delivery/${id}`);
      setDeliveries((prev) => prev.filter((d) => d._id !== id));
    } catch (error) {
      console.error("Failed to delete delivery:", error);
      alert("❌ Failed to delete delivery");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h1>Delivery Dashboard</h1>

      <div style={{ marginBottom: "20px" }}>
        <Link to="/create">
          <button style={{ padding: "10px", marginRight: "10px" }}>
            + New Delivery
          </button>
        </Link>

        <Link to="/add-driver">
          <button style={{ padding: "10px", marginRight: "10px" }}>
            + Add Driver
          </button>
        </Link>

        <Link to="/drivers">
          <button style={{ padding: "10px" }}>View Drivers</button>
        </Link>
      </div>

      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr style={{ backgroundColor: "#f0f0f0" }}>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>Customer ID</th>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>Status</th>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {deliveries.map((delivery) => (
            <tr key={delivery._id}>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>{delivery.customerId}</td>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>{delivery.status}</td>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>
                <Link to={`/delivery/${delivery._id}`}>
                  <button style={{ marginRight: "10px" }}>View</button>
                </Link>
                <button onClick={() => handleDelete(delivery._id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
